'use strict';
const {manufacturers}=window.HM_DATA;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let directoryCategory='All';
const label=m=>m.directory_category==='Robots'?'Robot maker':m.directory_category==='Kits'?'Kits & development':'Components';
function renderMakers(){const q=$('#makerSearch').value.toLowerCase().trim();const list=manufacturers.filter(m=>(directoryCategory==='All'||m.directory_category===directoryCategory)&&`${m.company} ${m.country} ${m.flagship_model} ${m.focus||''} ${m.component_category||''} ${label(m)} ${window.HM_I18N?.t(m.country)||''} ${window.HM_I18N?.t(m.focus)||''} ${window.HM_I18N?.t(label(m))||''}`.toLowerCase().includes(q));$('#makerCount').textContent=`${list.length} makers & suppliers`;$('#makerRows').innerHTML=list.map(m=>`<tr><td>${String(m.id).padStart(3,'0')}</td><td>${esc(m.company)}</td><td>${esc(label(m))}<small>${esc(m.component_category||'')}</small></td><td>${esc(m.country)}</td><td>${esc(m.flagship_model)}<small>${esc(m.form_factor)}</small></td><td>${esc(m.availability)}</td><td><a href="${esc(m.official_url)}" target="_blank" rel="noopener noreferrer" aria-label="Official source for ${esc(m.company)}">Official ↗</a></td></tr>`).join('')||'<tr><td colspan="7">No matching suppliers.</td></tr>';$('#allMakers').hidden=true;document.querySelectorAll('[data-directory]').forEach(b=>{b.classList.toggle('active',b.dataset.directory===directoryCategory);b.setAttribute('aria-pressed',String(b.dataset.directory===directoryCategory))})}
document.querySelectorAll('[data-directory]').forEach(b=>{const key=b.dataset.directory;b.innerHTML=b.textContent.replace(/\s+\d+$/,'')+` <span>${manufacturers.filter(m=>key==='All'||m.directory_category===key).length}</span>`;b.onclick=()=>{directoryCategory=key;renderMakers()}});
$('#downloadDirectory').onclick=()=>{const rows=[['Index','Manufacturer / supplier','Category','Base','Model / component','Focus','Status','Official source','Checked'],...manufacturers.map(m=>[m.id,m.company,label(m),m.country,m.flagship_model,m.component_category||'',m.availability,m.official_url,m.checked_date])];const csv=rows.map(row=>row.map(v=>'"'+String(window.HM_I18N?.t(v??'')??v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='humanoid-200-makers-and-suppliers.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#makerSearch').oninput=renderMakers;renderMakers();
